'use client'

import { useEffect, useState, type ChangeEvent } from 'react'
import { createClient } from '@/lib/supabase/client'
import { getUserRole } from '@/lib/supabase/roles'
import { ONBOARDING_STEPS, type OnboardingStepId, type VendorOnboardingDraft, type VendorOnboardingState, vendorOnboardingService } from '@/lib/vendor/onboarding'
import { VendorProgress } from './VendorProgress'
import { VendorStatusBadge } from './VendorStatusBadge'

const requiredFields: Record<string, string> = { companyName: 'Company name is required.', legalName: 'Legal name is required.', contactName: 'Contact name is required.', contactEmail: 'Contact email is required.', contactPhone: 'Contact phone is required.', businessType: 'Business type is required.', registrationNumber: 'Registration number is required.', operatingRegions: 'Operating regions are required.' }

export function VendorOnboardingForm() {
  const [state, setState] = useState<VendorOnboardingState | null>(null)
  const [activeStep, setActiveStep] = useState<OnboardingStepId>('company')
  const [vendorId, setVendorId] = useState<string | null>(null)
  const [isSaving, setIsSaving] = useState(false)
  const [message, setMessage] = useState<{ tone: 'success' | 'error'; text: string } | null>(null)
  const [errors, setErrors] = useState<Record<string, string>>({})

  useEffect(() => { let mounted = true; const supabase = createClient(); void supabase.auth.getUser().then(async ({ data: { user } }) => { if (!mounted || !user || (getUserRole(user) !== 'vendor' && getUserRole(user) !== 'admin')) return; setVendorId(user.id); setState(await vendorOnboardingService.getState(user.id)) }); return () => { mounted = false } }, [])

  if (!state || !vendorId) return <div className="vendor-loading" role="status">Loading your onboarding workspace...</div>
  const currentVendorId = vendorId
  const draft = state.draft
  const activeIndex = ONBOARDING_STEPS.findIndex((step) => step.id === activeStep)
  const activeStepConfig = ONBOARDING_STEPS[activeIndex]

  function updateDraft(field: keyof VendorOnboardingDraft, value: VendorOnboardingDraft[keyof VendorOnboardingDraft]) { setState((current) => current ? { ...current, draft: { ...current.draft, [field]: value } } : current); if (errors[field]) setErrors((current) => ({ ...current, [field]: '' })); setMessage(null) }
  function validateDraft() { const nextErrors: Record<string, string> = {}; Object.entries(requiredFields).forEach(([field, error]) => { if (!String(draft[field as keyof VendorOnboardingDraft] ?? '').trim()) nextErrors[field] = error }); if (!draft.documents.length) nextErrors.documents = 'Upload at least one required document.'; if (!draft.agreedToTerms) nextErrors.agreedToTerms = 'You must accept the vendor terms.'; if (!draft.catalogReady) nextErrors.catalogReady = 'Confirm your catalog is ready.'; setErrors(nextErrors); return Object.keys(nextErrors).length === 0 }
  async function saveDraft() { setIsSaving(true); setMessage(null); try { const nextState = await vendorOnboardingService.saveDraft(currentVendorId, draft); setState(nextState); setMessage({ tone: 'success', text: 'Your progress is saved. You can return here anytime.' }) } catch { setMessage({ tone: 'error', text: 'We could not save your progress. Please try again.' }) } finally { setIsSaving(false) } }
  async function submitOnboarding() { if (!validateDraft()) { setMessage({ tone: 'error', text: 'A few required details still need your attention.' }); return }; setIsSaving(true); try { setState(await vendorOnboardingService.submit(currentVendorId, draft)); setMessage({ tone: 'success', text: 'Your onboarding application has been submitted for review.' }) } catch { setMessage({ tone: 'error', text: 'We could not submit your application. Please try again.' }) } finally { setIsSaving(false) } }
  function moveStep(direction: number) { setActiveStep(ONBOARDING_STEPS[Math.max(0, Math.min(ONBOARDING_STEPS.length - 1, activeIndex + direction))].id); setMessage(null) }
  async function handleDocumentUpload(event: ChangeEvent<HTMLInputElement>) { const files = Array.from(event.target.files ?? []); if (!files.length) return; try { const uploaded = await Promise.all(files.map(async (file) => { const form = new FormData(); form.set('file', file); form.set('documentType', file.type || 'general'); const response = await fetch('/api/vendor/onboarding/documents', { method: 'POST', body: form }); if (!response.ok) throw new Error('Document upload failed.'); return await response.json() as VendorOnboardingDraft['documents'][number] })); updateDraft('documents', [...draft.documents, ...uploaded]); setErrors((current) => ({ ...current, documents: '' })); setMessage({ tone: 'success', text: 'Documents uploaded securely and are ready for review.' }) } catch { setMessage({ tone: 'error', text: 'We could not upload one or more documents. Please try again.' }) } finally { event.target.value = '' } }
  function renderField(field: keyof VendorOnboardingDraft, label: string, type = 'text', placeholder = '') { const value = draft[field]; if (typeof value !== 'string') return null; return <label className="vendor-field"><span>{label}{requiredFields[field] ? <b aria-hidden="true">*</b> : null}</span><input type={type} value={value} placeholder={placeholder} onChange={(event) => updateDraft(field, event.target.value)} aria-invalid={Boolean(errors[field])} />{errors[field] ? <small className="vendor-field-error">{errors[field]}</small> : null}</label> }

  return <div className="vendor-workspace"><VendorProgress activeStep={activeStep} statuses={state.stepStatuses} onSelect={setActiveStep} /><section className="vendor-form-panel" aria-labelledby="vendor-step-title"><div className="vendor-form-panel-head"><div><p className="vendor-eyebrow">Step {String(activeIndex + 1).padStart(2, '0')} of {ONBOARDING_STEPS.length}</p><h2 id="vendor-step-title">{activeStepConfig.label}</h2><p>{activeStepConfig.description}</p></div><div className="vendor-form-status"><strong>{state.completionPercent}%</strong><span>overall complete</span><VendorStatusBadge status={state.stepStatuses[activeStep]} /></div></div>
    {activeStep === 'company' ? <div className="vendor-form-grid">{renderField('companyName', 'Company name', 'text', 'The name customers will see')}{renderField('legalName', 'Legal name', 'text', 'Registered business name')}{renderField('website', 'Website', 'url', 'https://example.com')}</div> : null}
    {activeStep === 'contact' ? <div className="vendor-form-grid">{renderField('contactName', 'Primary contact', 'text', 'Full name')}{renderField('contactEmail', 'Contact email', 'email', 'name@company.com')}{renderField('contactPhone', 'Contact phone', 'tel', '+91')}</div> : null}
    {activeStep === 'business' ? <div className="vendor-form-grid">{renderField('businessType', 'Business type', 'text', 'Manufacturer, distributor, studio...')}{renderField('registrationNumber', 'Registration number', 'text', 'Business registration ID')}{renderField('taxId', 'Tax ID', 'text', 'Tax identifier')}{renderField('operatingRegions', 'Operating regions', 'text', 'Cities or regions you serve')}</div> : null}
    {activeStep === 'documents' ? <div className="vendor-document-area"><label className="vendor-upload-box"><input type="file" multiple accept="*/*" onChange={handleDocumentUpload} /><strong>Choose verification documents</strong><span>Any file type up to 25 MB can be uploaded for review.</span></label>{errors.documents ? <p className="vendor-field-error">{errors.documents}</p> : null}<div className="vendor-document-list">{draft.documents.map((document) => <div className="vendor-document-row" key={document.id}><span><strong>{document.name}</strong><small>{document.type} · {(document.size / 1024).toFixed(0)} KB</small></span><button type="button" onClick={() => updateDraft('documents', draft.documents.filter((item) => item.id !== document.id))}>Remove</button></div>)}</div></div> : null}
    {activeStep === 'agreement' ? <div className="vendor-confirmation-block"><p>Review the marketplace vendor agreement before submitting. The final legal copy and acceptance endpoint are intentionally pending the platform contract.</p><label className="vendor-checkbox"><input type="checkbox" checked={draft.agreedToTerms} onChange={(event) => updateDraft('agreedToTerms', event.target.checked)} /> <span>I agree to the vendor terms and marketplace policies.</span></label>{errors.agreedToTerms ? <p className="vendor-field-error">{errors.agreedToTerms}</p> : null}</div> : null}
    {activeStep === 'catalog' ? <div className="vendor-confirmation-block"><p>Catalog tools are part of a later phase. For onboarding, confirm that your initial product information is prepared for review.</p><label className="vendor-checkbox"><input type="checkbox" checked={draft.catalogReady} onChange={(event) => updateDraft('catalogReady', event.target.checked)} /> <span>My initial catalog information is ready for the next phase.</span></label>{errors.catalogReady ? <p className="vendor-field-error">{errors.catalogReady}</p> : null}</div> : null}
    {activeStep === 'completion' ? <div className="vendor-completion-block"><div className="vendor-completion-mark">{state.status === 'submitted' ? 'Submitted' : `${state.completionPercent}%`}</div><h3>{state.status === 'submitted' ? 'Application under review' : 'One thoughtful pass to go'}</h3><p>{state.status === 'submitted' ? 'Our team will review your onboarding details. You can return to this workspace to see the latest status.' : 'Complete the required steps, then submit when everything looks right.'}</p></div> : null}
    {message ? <div className={`vendor-message vendor-message-${message.tone}`} role="status">{message.text}</div> : null}<div className="vendor-form-actions"><button type="button" className="btn-skip" onClick={() => void saveDraft()} disabled={isSaving}>{isSaving ? 'Saving...' : 'Save and exit'}</button><div><button type="button" className="btn-skip" onClick={() => moveStep(-1)} disabled={activeIndex === 0}>Back</button>{activeStep === 'completion' ? <button type="button" className="btn-next" onClick={() => void submitOnboarding()} disabled={isSaving || state.status === 'submitted'}>Submit for review</button> : <button type="button" className="btn-next" onClick={() => moveStep(1)}>Continue</button>}</div></div></section></div>
}